INSERT IGNORE INTO knowledge_source_claims_v18 (claim_id,category,statement_zh,source_ids,evidence_locator,confidence,sensitivity,public_use,review_status,canonical_fingerprint,keywords,article_allowed,article_guardrail) VALUES ('kg_profile_plain_contact','族群簡介','卑南族長期定居於多族群交會的平原地帶，與外界接觸很早，但仍維持自身傳統、文化與生活方式。','["cip_pinuyumayan_profile_en_2021"]','L113-L115','high','low','public','verified_source_public_summary','claim_17cf0e52bbb67156','["卑南族", "平原", "文化維持", "族群簡介"]',1,'必須引用來源；不得加入未查證細節；中敏感祭儀/信仰內容只能摘要。');
INSERT IGNORE INTO knowledge_source_claims_v18 (claim_id,category,statement_zh,source_ids,evidence_locator,confidence,sensitivity,public_use,review_status,canonical_fingerprint,keywords,article_allowed,article_guardrail) VALUES ('kg_social_age_house','社會制度','卑南族以嚴謹的年齡階級與會所制度聞名，這是理解公共生活、教育與社會角色的重要線索。','["cip_pinuyumayan_profile_en_2021"]','L113-L115, L177-L179','high','medium','public_summary_only','verified_source_public_summary','claim_31b3fbf76b541f56','["年齡階級", "會所", "公共生活", "教育"]',1,'必須引用來源；不得加入未查證細節；中敏感祭儀/信仰內容只能摘要。');
INSERT IGNORE INTO knowledge_source_claims_v18 (claim_id,category,statement_zh,source_ids,evidence_locator,confidence,sensitivity,public_use,review_status,canonical_fingerprint,keywords,article_allowed,article_guardrail) VALUES ('kg_ritual_overview_public','歲時祭儀','公開資料可摘要說明卑南族年度祭儀包含小米除草完工、小米收穫、少年年祭與大獵祭等；涉及祭儀細節時必須保留摘要層級。','["cip_pinuyumayan_profile_en_2021"]','L115-L116, L185-L192','high','medium','public_summary_only','verified_source_public_summary','claim_9f0a42eef462fe30','["祭儀", "小米", "少年年祭", "大獵祭", "公開摘要"]',1,'必須引用來源；不得加入未查證細節；中敏感祭儀/信仰內容只能摘要。');
INSERT IGNORE INTO knowledge_source_claims_v18 (claim_id,category,statement_zh,source_ids,evidence_locator,confidence,sensitivity,public_use,review_status,canonical_fingerprint,keywords,article_allowed,article_guardrail) VALUES ('kg_name_pinuyumayan','族稱與命名','Pinuyumayan 作為族群稱呼，與南王部落名稱來源相關；平台應避免把 Puyuma 無脈絡地代稱整個族群。','["cip_pinuyumayan_profile_en_2021"]','L118-L119','high','low','public','verified_source_public_summary','claim_f94736a14d5e087a','["Pinuyumayan", "Puyuma", "南王", "族稱"]',1,'必須引用來源；不得加入未查證細節；中敏感祭儀/信仰內容只能摘要。');
INSERT IGNORE INTO knowledge_source_claims_v18 (claim_id,category,statement_zh,source_ids,evidence_locator,confidence,sensitivity,public_use,review_status,canonical_fingerprint,keywords,article_allowed,article_guardrail) VALUES ('kg_origin_systems_public','起源系統','公開資料將卑南族起源敘事概括為竹生與石生兩個來源系統；主站文章只可做公開摘要，不生成神聖敘事細節。','["cip_pinuyumayan_profile_en_2021"]','L119-L120','high','medium','public_summary_only','verified_source_public_summary','claim_8e30dab2bbd9aead','["竹生", "石生", "起源", "公開摘要"]',1,'必須引用來源；不得加入未查證細節；中敏感祭儀/信仰內容只能摘要。');
INSERT IGNORE INTO knowledge_source_claims_v18 (claim_id,category,statement_zh,source_ids,evidence_locator,confidence,sensitivity,public_use,review_status,canonical_fingerprint,keywords,article_allowed,article_guardrail) VALUES ('kg_distribution_taitung_center','分布','今日臺東市與卑南鄉的臺東平原地帶，是卑南族的重要中心。','["cip_pinuyumayan_profile_en_2021"]','L122-L124','high','low','public','verified_source_public_summary','claim_01d05646c8dbdb42','["臺東市", "卑南鄉", "臺東平原", "分布"]',1,'必須引用來源；不得加入未查證細節；中敏感祭儀/信仰內容只能摘要。');
