INSERT IGNORE INTO knowledge_source_claims_v18 (claim_id,category,statement_zh,source_ids,evidence_locator,confidence,sensitivity,public_use,review_status,canonical_fingerprint,keywords,article_allowed,article_guardrail) VALUES ('kg_wreath_public_summary','服飾與社會關係','花環在祭儀與生命階段中具有辨識與祝福意義；主站文章可摘要其社會關係意涵，不延伸臆造規範。','["cip_pinuyumayan_profile_en_2021"]','L136-L137','high','medium','public_summary_only','verified_source_public_summary','claim_6b87a7783f544136','["花環", "祭儀", "生命階段", "社會關係"]',1,'必須引用來源；不得加入未查證細節；中敏感祭儀/信仰內容只能摘要。');
