INSERT IGNORE INTO knowledge_source_claims_v18 (claim_id,category,statement_zh,source_ids,evidence_locator,confidence,sensitivity,public_use,review_status,canonical_fingerprint,keywords,article_allowed,article_guardrail) VALUES ('kg_music_song_public','音樂','卑南族音樂具有清楚節奏與敘事性，儀式歌、工作歌與聚會歌等依場合與社會角色有所區分。','["cip_pinuyumayan_profile_en_2021"]','L150-L156','high','low','public','verified_source_public_summary','claim_98cdc3b00ce9defc','["音樂", "儀式歌", "工作歌", "聚會歌"]',1,'必須引用來源；不得加入未查證細節；中敏感祭儀/信仰內容只能摘要。');
