INSERT IGNORE INTO knowledge_source_claims_v18 (claim_id,category,statement_zh,source_ids,evidence_locator,confidence,sensitivity,public_use,review_status,canonical_fingerprint,keywords,article_allowed,article_guardrail) VALUES ('kg_dance_public_roles','舞蹈','卑南族舞蹈與性別、年齡與祭儀場域相關；主站文章只可摘要公開文化意義，不生成儀式操作步驟。','["cip_pinuyumayan_profile_en_2021"]','L158-L161','high','medium','public_summary_only','verified_source_public_summary','claim_ef6ef6dcde37f208','["舞蹈", "性別", "年齡", "祭儀"]',1,'必須引用來源；不得加入未查證細節；中敏感祭儀/信仰內容只能摘要。');
INSERT IGNORE INTO knowledge_source_claims_v18 (claim_id,category,statement_zh,source_ids,evidence_locator,confidence,sensitivity,public_use,review_status,canonical_fingerprint,keywords,article_allowed,article_guardrail) VALUES ('kg_language_variation','族語','卑南語因部落與地理位置而有差異，知本、北部社群與漢人接觸語境皆會影響發音與使用。','["cip_pinuyumayan_profile_en_2021"]','L161-L164','high','low','public','verified_source_public_summary','claim_4b78354023476c54','["卑南語", "方言", "知本", "發音"]',1,'必須引用來源；不得加入未查證細節；中敏感祭儀/信仰內容只能摘要。');
INSERT IGNORE INTO knowledge_source_claims_v18 (claim_id,category,statement_zh,source_ids,evidence_locator,confidence,sensitivity,public_use,review_status,canonical_fingerprint,keywords,article_allowed,article_guardrail) VALUES ('kg_social_roles_public','社會角色','公開資料描述政治領袖、祭司與巫者等角色分工，分別維繫公共事務、祭儀知識與照護需求。','["cip_pinuyumayan_profile_en_2021"]','L164-L176','high','medium','public_summary_only','verified_source_public_summary','claim_cb02a43dbb2e11fa','["領袖", "祭司", "巫者", "社會角色"]',1,'必須引用來源；不得加入未查證細節；中敏感祭儀/信仰內容只能摘要。');
INSERT IGNORE INTO knowledge_source_claims_v18 (claim_id,category,statement_zh,source_ids,evidence_locator,confidence,sensitivity,public_use,review_status,canonical_fingerprint,keywords,article_allowed,article_guardrail) VALUES ('kg_matrilineal_public','親屬制度','公開資料指出卑南族傳統具有母系與從妻居特色，家名與財產繼承可與長女相關；當代實況需以部落與家庭脈絡審慎描述。','["cip_pinuyumayan_profile_en_2021"]','L170-L173','high','medium','public_summary_only','verified_source_public_summary','claim_f72b4eff112f0069','["母系", "從妻居", "繼承", "親屬"]',1,'必須引用來源；不得加入未查證細節；中敏感祭儀/信仰內容只能摘要。');
INSERT IGNORE INTO knowledge_source_claims_v18 (claim_id,category,statement_zh,source_ids,evidence_locator,confidence,sensitivity,public_use,review_status,canonical_fingerprint,keywords,article_allowed,article_guardrail) VALUES ('kg_youth_training_public','年齡階級教育','公開資料說明少年約十二至十三歲進入少年會所接受體能與知識訓練，之後再進入成年會所接受進一步技能訓練。','["cip_pinuyumayan_profile_en_2021"]','L177-L179','high','medium','public_summary_only','verified_source_public_summary','claim_188b9642cef45fcc','["少年會所", "成年會所", "訓練", "教育"]',1,'必須引用來源；不得加入未查證細節；中敏感祭儀/信仰內容只能摘要。');
INSERT IGNORE INTO knowledge_source_claims_v18 (claim_id,category,statement_zh,source_ids,evidence_locator,confidence,sensitivity,public_use,review_status,canonical_fingerprint,keywords,article_allowed,article_guardrail) VALUES ('kg_ritual_calendar_public','歲時祭儀月曆','公開資料將三月、四月、七月與十二月分別連結到除草完工、祭祖、小米收穫與年祭等年度節奏；主站可做月曆摘要。','["cip_pinuyumayan_profile_en_2021"]','L185-L192','high','medium','public_summary_only','verified_source_public_summary','claim_e22f56042dbbe43e','["三月", "四月", "七月", "十二月", "祭儀月曆"]',1,'必須引用來源；不得加入未查證細節；中敏感祭儀/信仰內容只能摘要。');
INSERT IGNORE INTO knowledge_source_claims_v18 (claim_id,category,statement_zh,source_ids,evidence_locator,confidence,sensitivity,public_use,review_status,canonical_fingerprint,keywords,article_allowed,article_guardrail) VALUES ('kg_masarut_public_summary','小米收穫祭','Masarut 可作為小米收穫祭公開摘要主題，文章應聚焦農耕節奏與文化活動，不生成祭儀程序教學。','["cip_pinuyumayan_profile_en_2021"]','L200-L203','high','medium','public_summary_only','verified_source_public_summary','claim_48afe9c8c762d006','["Masarut", "小米收穫祭", "農耕", "鞦韆"]',1,'必須引用來源；不得加入未查證細節；中敏感祭儀/信仰內容只能摘要。');
INSERT IGNORE INTO knowledge_source_claims_v18 (claim_id,category,statement_zh,source_ids,evidence_locator,confidence,sensitivity,public_use,review_status,canonical_fingerprint,keywords,article_allowed,article_guardrail) VALUES ('kg_mangayaw_public_summary','年祭','Mangayaw 是年末到歲初的重要年度活動，公開摘要可說明其包含少年年祭與大獵祭脈絡，但不得改寫為操作指南。','["cip_pinuyumayan_profile_en_2021"]','L204-L208','high','medium','public_summary_only','verified_source_public_summary','claim_3bc527b455a6335a','["Mangayaw", "年祭", "少年年祭", "大獵祭"]',1,'必須引用來源；不得加入未查證細節；中敏感祭儀/信仰內容只能摘要。');
INSERT IGNORE INTO knowledge_source_claims_v18 (claim_id,category,statement_zh,source_ids,evidence_locator,confidence,sensitivity,public_use,review_status,canonical_fingerprint,keywords,article_allowed,article_guardrail) VALUES ('kg_vasivas_societal_change','少年年祭','公開資料指出少年年祭中過去與猴相關的實作，在社會變遷後已以草猴取代真猴；主站應避免刺激性或獵奇描寫。','["cip_pinuyumayan_profile_en_2021"]','L209-L212','high','medium','public_summary_only','verified_source_public_summary','claim_8436fa406a819021','["Vasivas", "少年年祭", "草猴", "社會變遷"]',1,'必須引用來源；不得加入未查證細節；中敏感祭儀/信仰內容只能摘要。');
INSERT IGNORE INTO knowledge_source_claims_v18 (claim_id,category,statement_zh,source_ids,evidence_locator,confidence,sensitivity,public_use,review_status,canonical_fingerprint,keywords,article_allowed,article_guardrail) VALUES ('kg_joint_annual_ritual','聯合年祭','公開資料指出聯合年祭自 1982 年開始發展，時間由部落會議討論，並由不同部落輪流舉辦，具有族群認同連結意義。','["cip_pinuyumayan_profile_en_2021"]','L215-L216','high','low','public','verified_source_public_summary','claim_864a2af81edff186','["聯合年祭", "1982", "輪流舉辦", "族群認同"]',1,'必須引用來源；不得加入未查證細節；中敏感祭儀/信仰內容只能摘要。');
INSERT IGNORE INTO knowledge_source_claims_v18 (claim_id,category,statement_zh,source_ids,evidence_locator,confidence,sensitivity,public_use,review_status,canonical_fingerprint,keywords,article_allowed,article_guardrail) VALUES ('kg_population_stats_link','人口統計','人口數屬於會變動資料，主站文章只能引用官方統計頁與資料表，不可把舊數字當成最新人口。','["cip_population_stats_202406_page"]','L224-L232, L241-L288','high','low','public','verified_source_public_summary','claim_2a8cb7034511a0b2','["人口統計", "官方統計", "資料表"]',1,'必須引用來源；不得加入未查證細節；中敏感祭儀/信仰內容只能摘要。');
INSERT IGNORE INTO knowledge_source_claims_v18 (claim_id,category,statement_zh,source_ids,evidence_locator,confidence,sensitivity,public_use,review_status,canonical_fingerprint,keywords,article_allowed,article_guardrail) VALUES ('kg_audio_pronunciation_real_source','族語發音','族語發音公開播放應優先使用具來源與授權紀錄的真人音檔；未經審核的合成 TTS 不得冒充真人發音。','["formosanbank_puyuma_audio_public"]','project corpus metadata','medium','low','public','verified_source_public_summary','claim_e5758168eb7c9348','["真人音檔", "TTS", "族語", "發音"]',1,'必須引用來源；不得加入未查證細節；中敏感祭儀/信仰內容只能摘要。');
